(() => {'use strict';const buscar = seletor => document.querySelector(seletor);const contador = buscar('[data-restante]');const mensagem = texto => {const elemento = buscar('[data-mensagem]');if (elemento) {elemento.textContent = texto;elemento.classList?.add('mostrar');}};let som = false;let audio;let instalacao;try { som = localStorage.getItem('quizSom') === 'sim'; } catch {}function iniciarAudio() {const ContextoAudio = window.AudioContext || window.webkitAudioContext;if (ContextoAudio) audio = new ContextoAudio();}function tocar() {if (!som || !audio) return;const oscilador = audio.createOscillator();const ganho = audio.createGain();oscilador.frequency.value = 880;ganho.gain.setValueAtTime(0.035, audio.currentTime);ganho.gain.exponentialRampToValueAtTime(0.001, audio.currentTime + 0.07);oscilador.connect(ganho);ganho.connect(audio.destination);oscilador.start();oscilador.stop(audio.currentTime + 0.08);}const botaoSom = buscar('[data-som]');if (botaoSom) {botaoSom.setAttribute('aria-pressed', String(som));botaoSom.setAttribute('aria-label', som ? 'Desativar som' : 'Ativar som');}if (contador && som) {try { iniciarAudio(); } catch { mensagem('O som não está disponível neste navegador.'); }}if (contador) {const inicio = performance.now();const limite = Number(contador.dataset.restante);let ultimo = -1;function atualizar() {const restante = Math.max(0, limite - (performance.now() - inicio));const segundos = Math.ceil(restante / 1000);const pavio = (Math.min(1, restante / (Number(contador.dataset.segundos) * 1000)) * 100) + '%';buscar('[data-digitos]').textContent = String(segundos).padStart(2, '0');buscar('[data-pavio]').style.width = pavio;buscar('.pavio .faisca').style.left = pavio;document.body.classList.toggle('perigo', segundos <= Number(contador.dataset.alerta));document.body.classList.toggle('tremor', segundos <= 3);if (segundos !== ultimo && segundos <= Number(contador.dataset.alerta) && segundos > 0) tocar();ultimo = segundos;if (restante === 0) {buscar('[data-expiracao]').requestSubmit();return;}requestAnimationFrame(atualizar);}atualizar();}document.addEventListener('submit', evento => {if (evento.target.dataset.enviando) evento.preventDefault();else evento.target.dataset.enviando = 'sim';});document.addEventListener('keydown', evento => {if (!contador || evento.ctrlKey || evento.metaKey || evento.altKey || evento.repeat || ['INPUT', 'TEXTAREA'].includes(evento.target.tagName)) return;const tecla = evento.key.toLowerCase();let indice = 'abcde'.indexOf(tecla);if (indice < 0) indice = '12345'.indexOf(tecla);if (tecla.length === 1 && indice >= 0) {evento.preventDefault();buscar('[data-alternativa="' + indice + '"]')?.click();}});window.addEventListener('beforeinstallprompt', evento => { evento.preventDefault(); instalacao = evento; });document.addEventListener('click', async evento => {const elemento = evento.target.closest('[data-som], [data-instalar], [data-resultado]');if (!elemento) return;if (elemento.hasAttribute('data-som')) {som = !som;elemento.setAttribute('aria-pressed', String(som));elemento.setAttribute('aria-label', som ? 'Desativar som' : 'Ativar som');try {localStorage.setItem('quizSom', som ? 'sim' : 'nao');if (som) { iniciarAudio(); tocar(); }} catch { mensagem('O som não está disponível neste navegador.'); }} else if (elemento.hasAttribute('data-instalar')) {if (instalacao) {try { await instalacao.prompt(); await instalacao.userChoice; } catch { mensagem('Não foi possível abrir a instalação.'); }instalacao = null;} else mensagem('Abra o menu do navegador e escolha Adicionar à tela inicial.');} else {try { await navigator.clipboard.writeText(elemento.dataset.resultado); mensagem('Resultado copiado.'); }catch { mensagem(elemento.dataset.resultado); }}});window.addEventListener('pageshow', evento => {if (evento.persisted) window.location.reload();});})();